const CONDITION_SVGS: Record<string, string> = {
  "Clear": clearSvg,
  "Mainly Clear": mainlyClearSvg,
  "Partly Cloudy": partlyCloudySvg,
  "Overcast": overcastSvg,
  "Fog": fogSvg,
  "Lightning": lightningSvg,
  "Drizzle": rainSvg,
  "Rain": rainSvg,
  "Rain Showers": rainShowersSvg,
  "Snow": snowSvg,
  "Snow Grains": snowSvg,
  "Snow Showers": snowSvg,
  "Thunderstorm": thunderstormSvg,
  "Tornado": tornadoSvg,
};

const CONDITION_COLOR_SVGS: Record<string, string> = {
  "Clear": clearColorSvg,
  "Mainly Clear": mainlyClearColorSvg,
  "Partly Cloudy": partlyCloudyColorSvg,
  "Overcast": overcastColorSvg,
  "Fog": fogColorSvg,
  "Lightning": lightningColorSvg,
  "Drizzle": rainColorSvg,
  "Rain": rainColorSvg,
  "Rain Showers": rainShowersColorSvg,
  "Snow": snowColorSvg,
  "Snow Grains": snowColorSvg,
  "Snow Showers": snowColorSvg,
  "Thunderstorm": thunderstormColorSvg,
  "Tornado": tornadoColorSvg,
};

export function getWeatherIcon(condition: string): string {
  return CONDITION_SVGS[condition] ?? unknownSvg;
}

export function getWeatherIconColor(condition: string): string {
  return CONDITION_COLOR_SVGS[condition] ?? unknownColorSvg;
}
